/// Typed errors reported by the `calendar` module.
public enum CalendarError: Error, LocalizedError, Sendable {
    /// The date does not exist, or is outside 1 January of year 1 (18 Teves 3761) to 29 Elul 9999.
    case invalidDate(message: String)
    /// A day of Chanukah outside 1 to 8, or of the Omer outside 1 to 49.
    case invalidSpecialDay(message: String)

    /// The message the library reported, or the code's documented default.
    public var errorDescription: String? {
        switch self {
        case let .invalidDate(message): return message
        case let .invalidSpecialDay(message): return message
        }
    }

    /// The numeric ABI code carried by this error.
    public var errorCode: Int32 {
        switch self {
        case .invalidDate: return 1
        case .invalidSpecialDay: return 2
        }
    }
}

func wvMapCalendar(_ err: WvError) -> Error {
    let message = wvErrorMessage(err)
    switch err.code {
    case 1: return CalendarError.invalidDate(message: message.isEmpty ? "The date does not exist, or is outside 1 January of year 1 (18 Teves 3761) to 29 Elul 9999." : message)
    case 2: return CalendarError.invalidSpecialDay(message: message.isEmpty ? "A day of Chanukah outside 1 to 8, or of the Omer outside 1 to 49." : message)
    default: return wvRuntimeError(err)
    }
}

func wvCheckCalendar(_ err: inout WvError) throws {
    guard err.code != 0 else { return }
    let error = wvMapCalendar(err)
    kosherz_error_clear(&err)
    throw error
}

/// Where the calendar is kept. Outside Israel, Yom Tov has a second day.
public enum Region: Int32, Sendable {
    /// Eretz Yisrael: one day of Yom Tov.
    case israel = 0
    /// Everywhere else: two days of Yom Tov.
    case diaspora = 1
}

extension Region: WvCEnum {}

/// A month of the Hebrew calendar, numbered from Tishrei. A leap year has two Adars:
/// `AdarI` is the added month, and `Adar` is Adar II in a leap year.
public enum HebrewMonth: Int32, Sendable {
    /// Tishrei.
    case tishrei = 1
    /// Cheshvan.
    case cheshvan = 2
    /// Kislev.
    case kislev = 3
    /// Teves.
    case teves = 4
    /// Shevat.
    case shevat = 5
    /// Adar I, only in a leap year.
    case adarI = 6
    /// Adar, or Adar II in a leap year.
    case adar = 7
    /// Nisan.
    case nisan = 8
    /// Iyar.
    case iyar = 9
    /// Sivan.
    case sivan = 10
    /// Tammuz.
    case tammuz = 11
    /// Av.
    case av = 12
    /// Elul.
    case elul = 13
}

extension HebrewMonth: WvCEnum {}

