/// show them.
public enum SpecialDay: Hashable, Sendable {
    /// Erev Pesach, 14 Nisan.
    case erevPesach
    /// Pesach.
    case pesach
    /// Chol Hamoed Pesach.
    case cholHamoedPesach
    /// Pesach Sheni, 14 Iyar.
    case pesachSheni
    /// Erev Shavuos, 5 Sivan.
    case erevShavuos
    /// Shavuos.
    case shavuos
    /// The fast of 17 Tammuz.
    case seventeenthOfTammuz
    /// Tishah B'Av.
    case tishahBav
    /// Tu B'Av, 15 Av.
    case tuBav
    /// Erev Rosh Hashana, 29 Elul.
    case erevRoshHashana
    /// Rosh Hashana.
    case roshHashana
    /// The Fast of Gedalyah.
    case fastOfGedalyah
    /// Erev Yom Kippur, 9 Tishrei.
    case erevYomKippur
    /// Yom Kippur, 10 Tishrei.
    case yomKippur
    /// Erev Succos, 14 Tishrei.
    case erevSuccos
    /// Succos.
    case succos
    /// Chol Hamoed Succos.
    case cholHamoedSuccos
    /// Hoshana Rabbah, 21 Tishrei.
    case hoshanaRabbah
    /// Shemini Atzeres.
    case sheminiAtzeres
    /// Simchas Torah.
    case simchasTorah
    /// Chanukah.
    case chanukah(day: Int32)
    /// The fast of 10 Teves.
    case tenthOfTeves
    /// Tu B'Shvat, 15 Shevat.
    case tuBshvat
    /// The Fast of Esther.
    case fastOfEsther
    /// Purim.
    case purim
    /// Shushan Purim.
    case shushanPurim
    /// Purim Katan, 14 Adar I.
    case purimKatan
    /// Rosh Chodesh.
    case roshChodesh
    /// Yom HaShoah.
    case yomHaShoah
    /// Yom HaZikaron.
    case yomHaZikaron
    /// Yom HaAtzmaut.
    case yomHaAtzmaut
    /// Yom Yerushalayim.
    case yomYerushalayim
    /// Lag B'Omer, 18 Iyar.
    case lagBomer
    /// Shushan Purim Katan, 15 Adar I.
