    case shabbosMevarchim
}

extension SpecialDay: WvCodable {
    static func wvRead(_ r: inout WvReader) -> SpecialDay {
        let tag = r.readI32()
        switch tag {
        case 0: return .erevPesach
        case 1: return .pesach
        case 2: return .cholHamoedPesach
        case 3: return .pesachSheni
        case 4: return .erevShavuos
        case 5: return .shavuos
        case 6: return .seventeenthOfTammuz
        case 7: return .tishahBav
        case 8: return .tuBav
        case 9: return .erevRoshHashana
        case 10: return .roshHashana
        case 11: return .fastOfGedalyah
        case 12: return .erevYomKippur
        case 13: return .yomKippur
        case 14: return .erevSuccos
        case 15: return .succos
        case 16: return .cholHamoedSuccos
        case 17: return .hoshanaRabbah
        case 18: return .sheminiAtzeres
        case 19: return .simchasTorah
        case 20: return .chanukah(day: r.read())
        case 21: return .tenthOfTeves
        case 22: return .tuBshvat
        case 23: return .fastOfEsther
        case 24: return .purim
        case 25: return .shushanPurim
