/// A day on the Hebrew calendar: the civil day it mostly overlaps, since a Hebrew day
/// begins at nightfall. It covers 1 January of year 1 (18 Teves 3761) to 29 Elul 9999.
public final class HebrewDate: @unchecked Sendable {
    let ptr: OpaquePointer

    init(ptr: OpaquePointer) {
        self.ptr = ptr
    }

    deinit {
        kosherz_calendar_HebrewDate_destroy(ptr)
    }

    /// Returns a new strong reference to the same object, for a position that
    /// takes ownership of it.
    func clonePtr() -> OpaquePointer {
        wvNonNull(kosherz_calendar_HebrewDate_clone(ptr))
    }

    /// The date `day` `month` `year`, for example 15 Nisan 5785.
    ///
    /// # Errors
    ///
    /// `CalendarError::InvalidDate` when there is no such day: day 0, day 30 of a 29-day
    /// month, Adar I in a common year, or a year outside the supported range.
    ///
    /// - Throws: ``CalendarError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public init(year: Int32, month: HebrewMonth, day: Int32) throws {
        wvLoad()
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_new(year, kosherz_calendar_HebrewMonth(rawValue: numericCast(month.rawValue)), day, &err)
        try wvCheckCalendar(&err)
        self.ptr = wvNonNull(rv)
    }

    /// The Hebrew date of a Gregorian date.
    ///
    /// # Errors
    ///
    /// `CalendarError::InvalidDate` when `date` does not exist, or falls outside 1 January of
    /// year 1 to 29 Elul 9999.
    ///
    /// - Throws: ``CalendarError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public static func fromGregorian(date: GregorianDate) throws -> HebrewDate {
        wvLoad()
        var err = WvError()
        let rv: OpaquePointer? = wvWithEncoded(date) { date_ptr, date_len in
            kosherz_calendar_HebrewDate_from_gregorian(date_ptr, date_len, &err)
        }
        try wvCheckCalendar(&err)
        return HebrewDate(ptr: wvNonNull(rv))
    }

    /// The year, for example 5785.
    public func year() -> Int32 {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_year(ptr, &err)
        wvTrap(&err)
        return rv
    }

    /// The month.
    public func month() -> HebrewMonth {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_month(ptr, &err)
        wvTrap(&err)
        return wvEnumCase(HebrewMonth.self, numericCast(rv.rawValue))
    }

    /// The day of the month, from 1.
    public func day() -> Int32 {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_day(ptr, &err)
        wvTrap(&err)
        return rv
    }

    /// The day of the year, from 1 on 1 Tishrei.
    public func dayOfYear() -> Int32 {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_day_of_year(ptr, &err)
        wvTrap(&err)
        return rv
    }

    /// The day of the week.
    public func weekday() -> Weekday {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_weekday(ptr, &err)
        wvTrap(&err)
        return wvEnumCase(Weekday.self, numericCast(rv.rawValue))
    }

    /// The Gregorian date, if it is in the Gregorian calendar's supported range.
    public func toGregorian() -> GregorianDate? {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_to_gregorian(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: GregorianDate?.self)
    }

    /// The date `days` later, or earlier when negative.
    ///
    /// # Errors
    ///
    /// `CalendarError::InvalidDate` outside 1 January of year 1 to 29 Elul 9999.
    ///
    /// - Throws: ``CalendarError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public func addDays(days: Int32) throws -> HebrewDate {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_add_days(ptr, days, &err)
        try wvCheckCalendar(&err)
        return HebrewDate(ptr: wvNonNull(rv))
    }

    /// The holidays, fasts and other marked days on this day.
    public func specialDays(region: Region) -> [SpecialDay] {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_special_days(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: [SpecialDay].self)
    }

    /// Whether melacha is forbidden: Shabbos or Yom Tov.
    public func isAssurBemelacha(region: Region) -> Bool {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_is_assur_bemelacha(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &err)
        wvTrap(&err)
        return rv
    }

    /// Whether candles are lit tonight for Shabbos or Yom Tov.
    public func hasCandleLighting(region: Region) -> Bool {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_has_candle_lighting(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &err)
        wvTrap(&err)
        return rv
    }

    /// Whether this is one of the ten days from Rosh Hashana to Yom Kippur.
    public func isAseresYemeiTeshuva() -> Bool {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_is_aseres_yemei_teshuva(ptr, &err)
        wvTrap(&err)
        return rv
    }

    /// The weekly portion read on this day, when it is a Shabbos with one.
    public func parsha(region: Region) -> Parsha? {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_parsha(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Parsha?.self)
    }

    /// The special Shabbos this is, such as Shabbos Zachor, if any.
    public func specialParsha(region: Region) -> Parsha? {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_special_parsha(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Parsha?.self)
    }

    /// The weekly portion of the coming Shabbos.
    public func nextParsha(region: Region) -> Parsha? {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_next_parsha(ptr, kosherz_calendar_Region(rawValue: numericCast(region.rawValue)), &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Parsha?.self)
    }

    /// The molad of this month, in Unix milliseconds.
    public func molad() -> Int64? {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_molad(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Int64?.self)
    }

    /// The date as text, for example "15 Nisan 5784".
    public func display() -> String {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_calendar_HebrewDate_display(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeString(rv, outLen)
    }

    /// Whether `other` is the same day.
    public func equals(other: HebrewDate) -> Bool {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_equals(ptr, other.ptr, &err)
        wvTrap(&err)
        return rv
    }

    /// -1, 0 or 1 as this date is before, the same as, or after `other`.
    public func compare(other: HebrewDate) -> Int32 {
        var err = WvError()
        let rv = kosherz_calendar_HebrewDate_compare(ptr, other.ptr, &err)
        wvTrap(&err)
        return rv
    }
}

extension HebrewDate: WvCodable {
    static func wvRead(_ r: inout WvReader) -> HebrewDate { HebrewDate(ptr: r.readObject()) }
    func wvWrite(_ w: inout WvWriter) { w.writeObject(clonePtr()) }
}

/// Typed errors reported by the `calendar.limudim` module.
public enum LimudimError: Error, LocalizedError, Sendable {
    /// A psalm outside 1 to 150, a verse outside 1 to 176, a chapter of Pirkei Avos outside 1
    /// to 6, or a range that ends before it starts.
    case invalidUnit(message: String)

    /// The message the library reported, or the code's documented default.
    public var errorDescription: String? {
        switch self {
        case let .invalidUnit(message): return message
        }
    }

    /// The numeric ABI code carried by this error.
    public var errorCode: Int32 {
        switch self {
        case .invalidUnit: return 1
        }
    }
}

func wvMapCalendarLimudim(_ err: WvError) -> Error {
    let message = wvErrorMessage(err)
    switch err.code {
    case 1: return LimudimError.invalidUnit(message: message.isEmpty ? "A psalm outside 1 to 150, a verse outside 1 to 176, a chapter of Pirkei Avos outside 1" : message)
    default: return wvRuntimeError(err)
    }
}

func wvCheckCalendarLimudim(_ err: inout WvError) throws {
    guard err.code != 0 else { return }
    let error = wvMapCalendarLimudim(err)
    kosherz_error_clear(&err)
    throw error
}

