/// A day's portion of Tehillim.
public enum TehillimUnit: Hashable, Sendable {
    /// Whole chapters, `start` to `end` inclusive.
    case psalms(start: Int32, end: Int32)
    /// Part of one long chapter (119, split over two days).
    case psalmVerses(psalm: Int32, startVerse: Int32, endVerse: Int32)
}

extension TehillimUnit: WvCodable {
    static func wvRead(_ r: inout WvReader) -> TehillimUnit {
        let tag = r.readI32()
        switch tag {
        case 0: return .psalms(start: r.read(), end: r.read())
        case 1: return .psalmVerses(psalm: r.read(), startVerse: r.read(), endVerse: r.read())
        default: wvDecodeFailure("unknown TehillimUnit tag \(tag)")
        }
    }

    func wvWrite(_ w: inout WvWriter) {
        switch self {
        case let .psalms(v0, v1):
            w.writeI32(0)
            w.write(v0)
            w.write(v1)
        case let .psalmVerses(v0, v1, v2):
            w.writeI32(1)
            w.write(v0)
            w.write(v1)
            w.write(v2)
        }
    }
}

