    /// The second, the next *mishnah* in order.
    public var second: Mishna
    /// As text, for example "Nazir 5:5-6".
    public var display: String

    /// Creates a value from its fields.
    public init(first: Mishna, second: Mishna, display: String) {
        self.first = first
        self.second = second
        self.display = display
    }
}

extension MishnaPair: WvCodable {
    static func wvRead(_ r: inout WvReader) -> MishnaPair {
        MishnaPair(first: r.read(), second: r.read(), display: r.read())
    }

    func wvWrite(_ w: inout WvWriter) {
        w.write(self.first)
        w.write(self.second)
        w.write(self.display)
    }
}

/// Typed errors reported by the `times` module.
public enum ZmanimError: Error, LocalizedError, Sendable {
    /// The latitude is not between -90 and 90 degrees.
    case invalidLatitude(message: String)
    /// The longitude is not between -180 and 180 degrees.
    case invalidLongitude(message: String)
    /// An elevation is negative or not a finite number.
    case invalidElevation(message: String)
    /// The Gregorian date does not exist, or is outside the supported range.
    case invalidGregorianDate(message: String)
    /// A local day is needed and none was given. The four Kiddush Levana times need one.
    /// `Zmanim` and `MyZmanim` also need one at a location more than 150 degrees from
    /// Greenwich.
    case timeZoneRequired(message: String)
    /// The local day is impossible.
    ///
    /// It ends before it starts or more than 48 hours after, or an offset is a day or more.
    case invalidLocalDay(message: String)
    /// A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number
    /// within a day (1440 minutes) either way.
    case invalidMinutes(message: String)
    /// An angle in degrees is not a number from -90 to 90.
    case invalidDegrees(message: String)
    /// The sun stays above the angle the time needs all day, as in the far north in summer.
    case allDay(message: String)
    /// The sun stays below the angle the time needs all day, as in the far north in winter.
    case allNight(message: String)
    /// The time only exists on certain dates, and this is not one.
    case notApplicable(message: String)
    /// A calculation failed in a way that should not happen; please report the location and
    /// date.
    case unexpected(message: String)

    /// The message the library reported, or the code's documented default.
    public var errorDescription: String? {
        switch self {
        case let .invalidLatitude(message): return message
        case let .invalidLongitude(message): return message
        case let .invalidElevation(message): return message
        case let .invalidGregorianDate(message): return message
        case let .timeZoneRequired(message): return message
        case let .invalidLocalDay(message): return message
        case let .invalidMinutes(message): return message
        case let .invalidDegrees(message): return message
        case let .allDay(message): return message
        case let .allNight(message): return message
        case let .notApplicable(message): return message
        case let .unexpected(message): return message
        }
    }

    /// The numeric ABI code carried by this error.
    public var errorCode: Int32 {
        switch self {
        case .invalidLatitude: return 1
        case .invalidLongitude: return 2
        case .invalidElevation: return 3
        case .invalidGregorianDate: return 4
        case .timeZoneRequired: return 5
        case .invalidLocalDay: return 6
        case .invalidMinutes: return 7
        case .invalidDegrees: return 8
        case .allDay: return 10
        case .allNight: return 11
        case .notApplicable: return 12
        case .unexpected: return 13
        }
    }
}

func wvMapTimes(_ err: WvError) -> Error {
    let message = wvErrorMessage(err)
    switch err.code {
    case 1: return ZmanimError.invalidLatitude(message: message.isEmpty ? "The latitude is not between -90 and 90 degrees." : message)
    case 2: return ZmanimError.invalidLongitude(message: message.isEmpty ? "The longitude is not between -180 and 180 degrees." : message)
    case 3: return ZmanimError.invalidElevation(message: message.isEmpty ? "An elevation is negative or not a finite number." : message)
    case 4: return ZmanimError.invalidGregorianDate(message: message.isEmpty ? "The Gregorian date does not exist, or is outside the supported range." : message)
    case 5: return ZmanimError.timeZoneRequired(message: message.isEmpty ? "A local day is needed and none was given. The four Kiddush Levana times need one." : message)
    case 6: return ZmanimError.invalidLocalDay(message: message.isEmpty ? "The local day is impossible." : message)
    case 7: return ZmanimError.invalidMinutes(message: message.isEmpty ? "A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number" : message)
    case 8: return ZmanimError.invalidDegrees(message: message.isEmpty ? "An angle in degrees is not a number from -90 to 90." : message)
    case 10: return ZmanimError.allDay(message: message.isEmpty ? "The sun stays above the angle the time needs all day, as in the far north in summer." : message)
    case 11: return ZmanimError.allNight(message: message.isEmpty ? "The sun stays below the angle the time needs all day, as in the far north in winter." : message)
    case 12: return ZmanimError.notApplicable(message: message.isEmpty ? "The time only exists on certain dates, and this is not one." : message)
    case 13: return ZmanimError.unexpected(message: message.isEmpty ? "A calculation failed in a way that should not happen; please report the location and" : message)
    default: return wvRuntimeError(err)
    }
}

func wvCheckTimes(_ err: inout WvError) throws {
    guard err.code != 0 else { return }
    let error = wvMapTimes(err)
    kosherz_error_clear(&err)
    throw error
}

