/// A place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
/// leave them 0 for sea level.
///
/// The time zone is not part of the location. You pass a `LocalDay` to `Zmanim` and
/// `MyZmanim` when you create them.
public struct Location: Hashable, Sendable {
    /// Latitude in degrees, north positive.
    public var latitude: Double
    /// Longitude in degrees, east positive.
    public var longitude: Double
    /// The observer's height. Elevation makes sunrise earlier and sunset later.
    public var elevation: Double
    /// The height of the eastern horizon, over which the sun rises.
    public var easternHorizonElevation: Double
    /// The height of the western horizon, behind which the sun sets.
    public var westernHorizonElevation: Double

    /// Creates a value from its fields.
    public init(latitude: Double, longitude: Double, elevation: Double, easternHorizonElevation: Double, westernHorizonElevation: Double) {
        self.latitude = latitude
        self.longitude = longitude
        self.elevation = elevation
        self.easternHorizonElevation = easternHorizonElevation
        self.westernHorizonElevation = westernHorizonElevation
    }
}

extension Location: WvCodable {
    static func wvRead(_ r: inout WvReader) -> Location {
        Location(latitude: r.read(), longitude: r.read(), elevation: r.read(), easternHorizonElevation: r.read(), westernHorizonElevation: r.read())
    }

    func wvWrite(_ w: inout WvWriter) {
        w.write(self.latitude)
        w.write(self.longitude)
        w.write(self.elevation)
        w.write(self.easternHorizonElevation)
        w.write(self.westernHorizonElevation)
    }
}

/// The date in the caller's time zone: when local midnight starts it, when local midnight
/// starts the next date, and the offset from UTC at each. Compute it with your platform's
/// time zone support, for example `date.atStartOfDay(zone)` and
/// `date.plusDays(1).atStartOfDay(zone)` in Java.
///
/// When the clocks skip midnight, the day starts at the first instant the clocks show that
/// day, such as 01:00. A day the clocks skip entirely starts and ends at the same instant.
///
/// The local day is optional. With one every time works. You can also leave it out. These do
/// not work without one:
///
/// - The four Kiddush Levana times return `ZmanimError::TimeZoneRequired`.
/// - `Zmanim` and `MyZmanim` cannot be created for a location more than 150 degrees from
///   Greenwich. Creating them returns `ZmanimError::TimeZoneRequired`.
public struct LocalDay: Hashable, Sendable {
    /// When local midnight starts the date, in Unix milliseconds.
    public var startMs: Int64
    /// The offset from UTC at `start_ms`, in seconds east.
    public var startOffsetSeconds: Int32
    /// When local midnight starts the next date, in Unix milliseconds.
    public var endMs: Int64
    /// The offset from UTC at `end_ms`, in seconds east.
    public var endOffsetSeconds: Int32

    /// Creates a value from its fields.
    public init(startMs: Int64, startOffsetSeconds: Int32, endMs: Int64, endOffsetSeconds: Int32) {
        self.startMs = startMs
        self.startOffsetSeconds = startOffsetSeconds
        self.endMs = endMs
        self.endOffsetSeconds = endOffsetSeconds
    }
}

extension LocalDay: WvCodable {
    static func wvRead(_ r: inout WvReader) -> LocalDay {
        LocalDay(startMs: r.read(), startOffsetSeconds: r.read(), endMs: r.read(), endOffsetSeconds: r.read())
    }

    func wvWrite(_ w: inout WvWriter) {
        w.write(self.startMs)
        w.write(self.startOffsetSeconds)
        w.write(self.endMs)
        w.write(self.endOffsetSeconds)
    }
}

/// How `Zmanim` calculates. `default_config` matches KosherJava's defaults.
public struct Config: Hashable, Sendable {
    /// How long before sea-level sunset candle lighting is, in minutes, from 0 to 1440.
    /// Default 18.
    public var candleLightingMinutes: Int32
    /// Whether proportional zmanim divide the day at astronomical *chatzos*. Default false.
    public var useAstronomicalChatzosForOtherZmanim: Bool
    /// Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
    /// and sunset themselves. Default false.
    public var useElevation: Bool
    /// How long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
    /// Default 40.
    public var ateretTorahSunsetMinutes: Int32
    /// Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
    /// sunset. Default true.
    public var useAstronomicalChatzos: Bool
    /// The solar position algorithm. Default NOAA.
    public var calculator: Calculator
    /// For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.
    public var applyDeltaT: Bool

    /// Creates a value from its fields.
    public init(candleLightingMinutes: Int32, useAstronomicalChatzosForOtherZmanim: Bool, useElevation: Bool, ateretTorahSunsetMinutes: Int32, useAstronomicalChatzos: Bool, calculator: Calculator, applyDeltaT: Bool) {
        self.candleLightingMinutes = candleLightingMinutes
        self.useAstronomicalChatzosForOtherZmanim = useAstronomicalChatzosForOtherZmanim
        self.useElevation = useElevation
        self.ateretTorahSunsetMinutes = ateretTorahSunsetMinutes
        self.useAstronomicalChatzos = useAstronomicalChatzos
        self.calculator = calculator
        self.applyDeltaT = applyDeltaT
    }
}

extension Config: WvCodable {
    static func wvRead(_ r: inout WvReader) -> Config {
        Config(candleLightingMinutes: r.read(), useAstronomicalChatzosForOtherZmanim: r.read(), useElevation: r.read(), ateretTorahSunsetMinutes: r.read(), useAstronomicalChatzos: r.read(), calculator: r.read(), applyDeltaT: r.read())
    }

    func wvWrite(_ w: inout WvWriter) {
        w.write(self.candleLightingMinutes)
        w.write(self.useAstronomicalChatzosForOtherZmanim)
        w.write(self.useElevation)
        w.write(self.ateretTorahSunsetMinutes)
        w.write(self.useAstronomicalChatzos)
        w.write(self.calculator)
        w.write(self.applyDeltaT)
    }
}

