/// The *zmanim* for one place on one day.
public final class Zmanim: @unchecked Sendable {
    let ptr: OpaquePointer

    init(ptr: OpaquePointer) {
        self.ptr = ptr
    }

    deinit {
        kosherz_times_Zmanim_destroy(ptr)
    }

    /// Returns a new strong reference to the same object, for a position that
    /// takes ownership of it.
    func clonePtr() -> OpaquePointer {
        wvNonNull(kosherz_times_Zmanim_clone(ptr))
    }

    /// The *zmanim* at `location` on `date`, whose local day is `local_day`, calculated with
    /// `config`.
    ///
    /// The local day is optional. With one every time works. Without one the four Kiddush
    /// Levana times return `ZmanimError::TimeZoneRequired`. A location more than 150 degrees
    /// from Greenwich needs one. Without one this returns `ZmanimError::TimeZoneRequired`.
    ///
    /// # Errors
    ///
    /// - `ZmanimError::InvalidGregorianDate` when the date does not exist.
    /// - `ZmanimError::InvalidMinutes` when the candle-lighting offset is negative, or it or the
    ///   Ateret Torah offset is more than a day.
    /// - `ZmanimError::InvalidLocalDay` when `local_day` is impossible.
    /// - The errors of `validate_location`. This includes `ZmanimError::TimeZoneRequired` when
    ///   there is no local day and the location is more than 150 degrees from Greenwich.
    ///
    /// - Throws: ``ZmanimError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public init(location: Location, date: GregorianDate, config: Config, localDay: LocalDay?) throws {
        wvLoad()
        var err = WvError()
        let rv: OpaquePointer? = wvWithEncoded(location) { location_ptr, location_len in
            wvWithEncoded(date) { date_ptr, date_len in
                wvWithEncoded(config) { config_ptr, config_len in
                    wvWithEncoded(localDay) { localDay_ptr, localDay_len in
                        kosherz_times_Zmanim_new(location_ptr, location_len, date_ptr, date_len, config_ptr, config_len, localDay_ptr, localDay_len, &err)
                    }
                }
            }
        }
        try wvCheckTimes(&err)
        self.ptr = wvNonNull(rv)
    }

    /// The time of `zman`, in Unix milliseconds.
    ///
    /// # Errors
    ///
    /// `ZmanimError::AllDay` or `ZmanimError::AllNight` where the sun never reaches
    /// the angle the time needs; `ZmanimError::NotApplicable` for a time that only exists
    /// on some days; `ZmanimError::TimeZoneRequired` for the Kiddush Levana times without
    /// a local day.
    ///
    /// - Throws: ``ZmanimError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public func get(zman: Zman) throws -> Int64 {
        var err = WvError()
        let rv = kosherz_times_Zmanim_get(ptr, kosherz_times_Zman(rawValue: numericCast(zman.rawValue)), &err)
        try wvCheckTimes(&err)
        return rv
    }

    /// Every zman, with its time or why it has none.
    public func all() -> [ZmanTime] {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_times_Zmanim_all(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: [ZmanTime].self)
    }

    /// When the sun is `degrees` below the geometric horizon before sunrise, in Unix
    /// milliseconds.
    ///
    /// # Errors
    ///
    /// `ZmanimError::InvalidDegrees` when `degrees` is not a number from -90 to 90; otherwise
    /// the same as `get`.
    ///
    /// - Throws: ``ZmanimError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public func sunriseOffsetByDegrees(degrees: Double) throws -> Int64 {
        var err = WvError()
        let rv = kosherz_times_Zmanim_sunrise_offset_by_degrees(ptr, degrees, &err)
        try wvCheckTimes(&err)
        return rv
    }

    /// When the sun is `degrees` below the geometric horizon after sunset, in Unix
    /// milliseconds.
    ///
    /// # Errors
    ///
    /// `ZmanimError::InvalidDegrees` when `degrees` is not a number from -90 to 90; otherwise
    /// the same as `get`.
    ///
    /// - Throws: ``ZmanimError`` for a declared failure, ``KosherzRuntimeError`` otherwise.
    public func sunsetOffsetByDegrees(degrees: Double) throws -> Int64 {
        var err = WvError()
        let rv = kosherz_times_Zmanim_sunset_offset_by_degrees(ptr, degrees, &err)
        try wvCheckTimes(&err)
        return rv
    }

    /// The location.
    public func location() -> Location {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_times_Zmanim_location(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Location.self)
    }

    /// The date.
    public func date() -> GregorianDate {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_times_Zmanim_date(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: GregorianDate.self)
    }

    /// The configuration, as given to `new`.
    public func config() -> Config {
        var err = WvError()
        var outLen = 0
        let rv = kosherz_times_Zmanim_config(ptr, &outLen, &err)
        wvTrap(&err)
        return wvTakeBuffer(rv, outLen, as: Config.self)
    }
}

extension Zmanim: WvCodable {
    static func wvRead(_ r: inout WvReader) -> Zmanim { Zmanim(ptr: r.readObject()) }
    func wvWrite(_ w: inout WvWriter) { w.writeObject(clonePtr()) }
}

